INSERT INTO feature VALUES('theory-terms','descriptions','A theory''s terms as a type (Terms(S))','signature-models','partial','notable',NULL,'`Terms(S)` is the data type of a theory''s closed terms, one constructor per operation, written `S.op` in a term and in a pattern. The theory''s rules orient as the data block''s own and are its conversion, and the derived declaration is the data block written by hand. `Terms S s` is the type of the terms of the sort `s` of a theory of several sorts, and each operation into the sort is a constructor. The terms of an indexed sort are a family over the terms of each index sort: `Terms S s i` is the type at the index `i`, each constructor stands at the closed index that its operation states, and a rule of the sort is a rule of the family. An index in a type is a variable or a term of the index sort, written `S.op`. A theory whose rules present no type is refused `RuleNotPresentable` at `Terms(S)`, and a declaration asking for those terms states that cause. A sort outside the slice is refused by name: one whose operation takes a term of another plain sort, one whose port states an index with a variable, and each sort of a theory that states a law. The terms as a model of their theory, a fold over a model value, an operation across two plain sorts and an index with a variable are owed.','surface-lowering surface-grammar surface-corpus','corpus/ledger/features/theory-terms.gandr corpus/model/desc/theory-terms.gandr corpus/pathological/desc/theory-terms.gandr corpus/model/desc/terms-of-a-sort.gandr corpus/pathological/desc/terms-of-a-sort.gandr crates/surface-lowering/tests/modules/models.rs crates/surface-corpus/src/settle.rs','corpus/ledger/features/theory-terms.gandr','#4148 #4149 #4150');
